// ring.go
package logfan

import (
    "context"
    "errors"
    "log/slog"
    "sync"
)

// Ring is an in-memory ring-buffer slog handler that keeps the most recent
// records up to a fixed capacity.
type Ring struct {
    mu       sync.Mutex
    buf      []slog.Record
    start    int
    count    int
    capacity int
    attrs    []slog.Attr
    group    string
}

// NewRing creates a Ring handler with the given capacity.
func NewRing(capacity int) (*Ring, error) {
    if capacity <= 0 {
        return nil, errors.New("logfan.NewRing: capacity must be positive")
    }
    return &Ring{
        buf:      make([]slog.Record, capacity),
        capacity: capacity,
    }, nil
}

// Enabled returns true for all levels.
func (r *Ring) Enabled(ctx context.Context, lvl slog.Level) bool {
    return true
}

// Handle adds a record to the ring buffer, evicting the oldest if full.
func (r *Ring) Handle(ctx context.Context, rec slog.Record) error {
    // Build a record that includes handler-level attrs.
    r2 := slog.NewRecord(rec.Time, rec.Level, rec.Message, rec.PC)
    if r.group != "" {
        r2.AddAttrs(slog.Group(r.group, r.attrs...))
    } else {
        for _, a := range r.attrs {
            r2.AddAttrs(a)
        }
    }
    rec.Attrs(func(a slog.Attr) bool {
        r2.AddAttrs(a)
        return true
    })

    r.mu.Lock()
    defer r.mu.Unlock()

    if r.count < r.capacity {
        pos := (r.start + r.count) % r.capacity
        r.buf[pos] = r2
        r.count++
    } else {
        r.buf[r.start] = r2
        r.start = (r.start + 1) % r.capacity
    }
    return nil
}

// WithAttrs returns a new Ring handler with the given attrs prepended.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
    newAttrs := make([]slog.Attr, 0, len(r.attrs)+len(attrs))
    newAttrs = append(newAttrs, r.attrs...)
    newAttrs = append(newAttrs, attrs...)
    return &Ring{
        buf:      r.buf,
        capacity: r.capacity,
        start:    r.start,
        count:    r.count,
        attrs:    newAttrs,
        group:    r.group,
    }
}
